// Sample fallback / Apify lead normalizer
// Accepts direct Apify items or provides test mock data
const inputData = $input.all();
let items = [];

if (inputData && inputData.length > 0 && inputData[0].json && (inputData[0].json.body || inputData[0].json.title || inputData[0].json.companyName)) {
  // Webhook payload from Apify
  const raw = inputData[0].json.body || inputData[0].json;
  items = Array.isArray(raw) ? raw : (raw.items || [raw]);
} else {
  // Demo / Test records representing Segment A and Segment B
  items = [
    {
      title: "Sri Murugan Builders & Contractors",
      phone: "+91 98421 55678",
      email: "info@srimuruganbuilders.com",
      website: "",
      city: "Madurai",
      address: "12 Bye Pass Road, Madurai, Tamil Nadu",
      totalScore: 4.8,
      reviewsCount: 24
    },
    {
      title: "Apex Turnkey Civil Constructions",
      phone: "919361599097",
      email: "contact@apexconstructions.in",
      website: "http://example-outdated-builder-site.com",
      city: "Coimbatore",
      address: "Avinashi Road, Coimbatore, Tamil Nadu",
      totalScore: 4.2,
      reviewsCount: 16
    }
  ];
}

return items.map(item => {
  // Normalize business name
  const businessName = (item.title || item.companyName || item.name || 'Valued Builder').trim();

  // Contact cleanup
  let rawPhone = (item.phone || item.phoneNumber || '').toString().replace(/[^0-9+]/g, '');
  if (rawPhone && !rawPhone.startsWith('+')) {
    if (rawPhone.length === 10) rawPhone = '+91' + rawPhone;
    else if (rawPhone.length === 12 && rawPhone.startsWith('91')) rawPhone = '+' + rawPhone;
  }

  const email = (item.email || '').trim().toLowerCase();
  let website = (item.website || item.url || '').trim();

  // Check if website is actually a social directory instead of custom domain
  const isDirectoryOrSocial = /(facebook\.com|instagram\.com|indiamart\.com|justdial\.com|linkedin\.com)/i.test(website);
  const hasDedicatedWebsite = Boolean(website && website.length > 8 && !isDirectoryOrSocial);

  return {
    json: {
      businessName,
      phone: rawPhone,
      email,
      rawWebsite: website,
      hasDedicatedWebsite,
      city: item.city || item.addressLocality || 'your area',
      address: item.address || '',
      rating: item.totalScore || item.rating || 0,
      reviewCount: item.reviewsCount || 0,
      source: 'Apify Google Maps'
    }
  };
});

const lead = $json;
const name = lead.businessName;
const location = lead.city || 'your area';

// WhatsApp copy for builders without a website
const whatsappMessage = 
  `Hi ${name},\n\n` +
  `I came across your construction business on Google Maps in ${location}. I noticed you do quality structural and house construction work, but couldn't find a dedicated website showcasing your completed projects.\n\n` +
  `Most homeowners compare 3-4 builders online before calling. Without a premium portfolio, many assume you're a smaller sub-contractor rather than a turnkey builder.\n\n` +
  `I help independent house builders launch a complete digital experience — including a modern project showcase, 360° virtual site tours, and a WhatsApp AI agent that pre-qualifies plot details and budget 24/7.\n\n` +
  `Would you be open to seeing a 2-minute concept layout I designed for builders in ${location}?`;

// Email copy for builders without a website
const emailSubject = `Dedicated project portfolio & quotation system for ${name}`;
const emailBody = 
  `Hi ${name} Team,\n\n` +
  `I was reviewing house builders and contractors in ${location} and noticed your Google Maps profile.\n\n` +
  `While your reviews reflect solid workmanship, you don't currently have a dedicated modern website to showcase your elevation plans, floor layouts, and completed handover walkthroughs.\n\n` +
  `Today's homeowners want to see tangible proof of construction quality before initiating a quotation enquiry. I build custom digital systems for independent contractors that include:\n` +
  `1. Premium Portfolio: High-res photos, 3D elevations, and 360° site walkthroughs\n` +
  `2. Instant Cost & BOQ Estimator: Filters tire-kickers by collecting plot size & budget upfront\n` +
  `3. WhatsApp AI Assistant: Captures homeowner leads and schedules soil tests / site meetings\n\n` +
  `Would you be open to seeing a quick concept tailored for ${name}?\n\n` +
  `Best regards,\nSuresh Kumar\nBuilder Digital Experience & Enquiry System™`;

return [{
  json: {
    ...lead,
    segment: "Segment A - No Website",
    outreachAngle: "New Website + Portfolio + WhatsApp AI",
    whatsappMessage,
    emailSubject,
    emailBody
  }
}];

const lead = $('Loop Over Leads (1 by 1)').first().json;
const httpResult = $input.first().json;

const isDownOrError = Boolean(httpResult.error || !httpResult);
const htmlBody = (typeof httpResult === 'string' ? httpResult : JSON.stringify(httpResult)).toLowerCase();

// Basic heuristics for outdated websites
const hasViewport = htmlBody.includes('viewport');
const hasWhatsAppWidget = htmlBody.includes('whatsapp') || htmlBody.includes('wa.me');
const hasModernFramework = htmlBody.includes('react') || htmlBody.includes('next') || htmlBody.includes('tailwind') || htmlBody.includes('webflow');

let segmentTag = "Segment B - Outdated Website / Redesign";
let specificObservation = "your site is missing modern interactive project showcases and instant WhatsApp quotation enquiry buttons";

if (isDownOrError) {
  segmentTag = "Segment B - Website Inaccessible / Broken";
  specificObservation = "your listed website appears to be down or having domain/SSL errors, which costs you homeowner enquiries daily";
} else if (!hasWhatsAppWidget) {
  specificObservation = "your website does not have an instant WhatsApp quotation button or BOQ calculator, causing mobile visitors to bounce without inquiring";
}

const name = lead.businessName;
const location = lead.city || 'your area';

// WhatsApp copy for website upgrade
const whatsappMessage = 
  `Hi ${name},\n\n` +
  `I came across your construction business and checked out your website (${lead.rawWebsite}).\n\n` +
  `You have great construction experience, but I noticed an opportunity: ${specificObservation}.\n\n` +
  `We help independent builders upgrade from a static brochure website to a 24/7 Enquiry Generation System — featuring 3D house visualizers, 360° virtual walkthroughs, and WhatsApp AI lead qualification.\n\n` +
  `Would you mind if I sent over a short 2-minute video showing 3 specific improvements for your site?`;

// Email copy for website upgrade
const emailSubject = `3 website & enquiry improvements for ${name}`;
const emailBody = 
  `Hi ${name} Team,\n\n` +
  `I came across your business while researching reputable house contractors in ${location} and reviewed your website (${lead.rawWebsite}).\n\n` +
  `Your completed projects show solid construction quality, but your digital journey could be converting significantly more quotation requests. Specifically: ${specificObservation}.\n\n` +
  `Homeowners today want to explore finished projects in 360°, check approximate construction packages per sq.ft, and start a WhatsApp conversation in one click.\n\n` +
  `We build the Builder Digital Experience & Enquiry System™ specifically for independent contractors to turn passive website visits into booked site inspections.\n\n` +
  `Would you be open to a quick 3-point audit showing how to modernize your project presentation?\n\n` +
  `Best regards,\nSuresh Kumar\nBuilder Digital Experience & Enquiry System™`;

return [{
  json: {
    ...lead,
    segment: segmentTag,
    outreachAngle: "Website Upgrade + 3D/360 + WhatsApp Automation",
    websiteStatus: isDownOrError ? 'Down/Error' : 'Active',
    whatsappMessage,
    emailSubject,
    emailBody
  }
}];

const lead = $('Loop Over Leads (1 by 1)').first().json;
const whatsappResult = $('Dispatch WhatsApp Outreach').first()?.json || null;
const emailResult = $('Dispatch Cold Email (Resend)').first()?.json || null;

return [{
  json: {
    businessName: lead.businessName,
    phone: lead.phone,
    email: lead.email,
    segment: lead.segment || 'Segment A',
    whatsappSent: Boolean(whatsappResult && !whatsappResult.error),
    emailSent: Boolean(emailResult && (emailResult.id || !emailResult.error)),
    timestamp: new Date().toISOString(),
    status: "OUTREACH_DISPATCHED"
  }
}];
